/**
 * Types for the bundled Traveller Ship Designer engine (ship-designer.js,
 * generated by scripts/vendor-ship-designer.mjs). Only what this project
 * reads is declared.
 */

export interface DesignerDesign {
  name: string;
  hull: { tons: number };
  military?: boolean;
  [key: string]: unknown;
}

export interface DesignerCrewEntry {
  role: string;
  label: string;
  count: number;
  salary: number;
}

export function parse(text: string): DesignerDesign | null;
export function sheet(design: DesignerDesign): { crew: DesignerCrewEntry[] };

export const SCOUT_COURIER: DesignerDesign;
export const FREE_TRADER: DesignerDesign;
export const PATROL_CORVETTE: DesignerDesign;
export const DESTROYER_ESCORT: DesignerDesign;
